mapper.insert:
insert ignore into ai_customer_conversation (
    conversation_id, member_id, title, create_time, update_time
) values (
    #{conversationId}, #{memberId}, #{title}, now(), now()
)

mapper.select:
select 
from ai_customer_conversation c
where c.conversation_id = #{conversationId}
  and c.member_id = #{memberId}
limit 1

select coalesce(max(sequence_no), 0) + 1
from ai_customer_conversation_message
where conversation_id = #{conversationId}

mapper.update:
update ai_customer_conversation
set title = #{title}, update_time = now()
where conversation_id = #{conversationId}
  and member_id = #{memberId}
  and title = #{defaultTitle}

update ai_customer_conversation
set update_time = now()
where conversation_id = #{conversationId}
  and member_id = #{memberId}

mapper.delete:
delete from ai_customer_conversation
where conversation_id = #{conversationId}
  and member_id = #{memberId}
